</nav><p>家计本 · 纯静态家庭记账站 · 数据仅存本地 · 示例账本仅供演示</p></footer>

<script>
window.addEventListener("DOMContentLoaded", function () {
  /* KPI：示例数 + 用户自己记的 11 月账（与分类页、月度页同一口径） */
  var t = effectiveMonthTotals("2026-11");
  var save = t.income - t.expense;
  document.getElementById("kpi-income").textContent = fmt(t.income);
  document.getElementById("kpi-expense").textContent = fmt(t.expense);
  document.getElementById("kpi-save").textContent = fmt(save);
  document.getElementById("kpi-rate").textContent = (save / t.income * 100).toFixed(1) + "%";
  document.getElementById("kpi-save-sub").textContent =
    (t.userIncome + t.userExpense > 0)
      ? "含你记的账：收入 +" + fmt(t.userIncome) + "，支出 +" + fmt(t.userExpense)
      : "收入 − 支出，全部可存起来";
  document.querySelector(".hero h1").textContent = "这个月，家里一共攒下 " + fmt(save);

  /* 近 6 个月：11 月一栏同样含用户账，其余月份是示例数 */
  var eff = effectiveMonths(), last6 = eff.slice(-6);
  drawGroupedBars(document.getElementById("chart-months"),
    last6.map(function (m) { return m.label; }),
    last6.map(function (m) { return m.income; }),
    last6.map(function (m) { return m.expense; }), "收入", "支出");

  /* 环形图：合并后的分类实际，与分类页同一份数字 */
  var cats = effectiveCategories("2026-11");
  document.getElementById("donut").innerHTML = donutSVG(
    cats.map(function (c) { return { value: c.actual, color: c.color }; }), 200);
  var top = cats[0];
  document.getElementById("donut-note").innerHTML =
    "<strong>住房 " + fmt(top.actual) + "</strong> 占 " + (top.actual / t.expense * 100).toFixed(1) + "%，是最大的一笔。";

  var rows = allTransactions().slice().sort(function (a, b) { return b.date < a.date ? -1 : 1; }).slice(0, 8);
  document.getElementById("recent").innerHTML = txRows(rows);

  /* 全年行：11 月含用户账 */
  var yi = 0, ye = 0;
  eff.forEach(function (m) { yi += m.income; ye += m.expense; });
  document.getElementById("year-line").textContent =
    "全年 1–11 月：收入 " + fmt(yi) + "，支出 " + fmt(ye) + "，已攒 " + fmt(yi - ye) + "。详情见「年度趋势」。";
});
</script>
</body>
</html>
