<script>
/* 记一笔页的本地逻辑：表单、自己记的账列表、完整账本三块。
   注意日期只认 2026-11-01 到 2026-11-30，超出这个月的账不往里记；
   收入只有“收入”一个分类，支出才按 11 类分。 */
let pickedType = "expense";
let pickedFilter = "all";

const $ = function (id) { return document.getElementById(id); };

function byDateDesc(a, b) {
  if (a.date === b.date) return 0;
  return a.date < b.date ? 1 : -1;
}

function rebuildCatSelect() {
  const sel = $("f-cat");
  if (pickedType === "income") {
    sel.innerHTML = `<option value="income">收入</option>`;
    return;
  }
  sel.innerHTML = SAMPLE.categories
    .map((c) => `<option value="${c.key}">${c.name}</option>`)
    .join("");
}

function netText(income, expense) {
  const net = income - expense;
  return net >= 0 ? fmt(net) : "−¥" + Math.abs(net).toLocaleString("zh-CN");
}

function refreshMyEntries() {
  const mine = loadUserEntries();
  let inc = 0, exp = 0;
  mine.forEach((e) => { if (e.type === "income") inc += e.amount; else exp += e.amount; });
  $("my-summary").textContent = mine.length
    ? `你记了 ${mine.length} 笔：收入 ${fmt(inc)}，支出 ${fmt(exp)}，净影响结余 ${netText(inc, exp)}。`
    : "你还没有记账。示例流水 40 笔不受影响，只展示你自己记的。";
  const indexed = mine.map((e, i) => ({ e, i })).sort((a, b) => byDateDesc(a.e, b.e));
  $("my-list").innerHTML = mine.length
    ? indexed.map((o) => {
        const e = o.e;
        const isIncome = e.type === "income";
        return `<tr><td>${e.date.slice(5)}</td><td>${e.name}</td><td>${catName(e.cat)}</td>` +
          `<td class="num ${isIncome ? "pos" : "neg"}">${isIncome ? "+" : "−"}${fmt(e.amount)}</td>` +
          `<td><button class="btn danger" data-i="${o.i}">删除</button></td></tr>`;
      }).join("")
    : `<tr><td colspan="5" class="small">暂无，快在左边记第一笔吧。</td></tr>`;
  document.querySelectorAll("#my-list .btn.danger").forEach((btn) => {
    btn.addEventListener("click", () => {
      const list = loadUserEntries();
      list.splice(parseInt(btn.getAttribute("data-i"), 10), 1);
      saveUserEntries(list);
      refreshMyEntries();
      refreshFullLedger();
    });
  });
}

function refreshFullLedger() {
  let list = allTransactions().slice().sort(byDateDesc);
  if (pickedFilter !== "all") list = list.filter((t) => t.type === pickedFilter);
  $("list-count").textContent = `共 ${list.length} 笔`;
  $("full-list").innerHTML = txRows(list);
}

function markOn(groupSelector, activeBtn) {
  document.querySelectorAll(groupSelector).forEach((x) => x.classList.toggle("on", x === activeBtn));
}

function submitEntry(ev) {
  ev.preventDefault();
  const amount = parseFloat($("f-amount").value);
  const name = $("f-name").value.trim();
  const msg = $("form-msg");
  if (!name || !(amount > 0)) {
    msg.textContent = "请把事项和金额都填好，金额要大于 0。";
    return;
  }
  const list = loadUserEntries();
  list.push({
    date: $("f-date").value,
    type: pickedType,
    cat: $("f-cat").value,
    name: name,
    amount: Math.round(amount * 100) / 100,
