<script>
function drawSaveBars(cv, labels, vals) {
  var s = setupCanvas(cv, 260), ctx = s.ctx, W = s.w, H = s.h;
  var padL = 46, padR = 10, padT = 14, padB = 26;
  var max = 0; vals.forEach(function (v) { if (v > max) max = v; });
  max = Math.ceil(max / 1000) * 1000;
  ctx.font = "12px sans-serif"; ctx.fillStyle = "#6b7a73"; ctx.strokeStyle = "#e2ddd2";
  for (var g = 0; g <= 4; g++) {
    var y = padT + (H - padT - padB) * g / 4, val = max * (1 - g / 4);
    ctx.beginPath(); ctx.moveTo(padL, y); ctx.lineTo(W - padR, y); ctx.stroke();
    ctx.textAlign = "right"; ctx.fillText("¥" + (val / 1000) + "k", padL - 6, y + 4);
  }
  var cw = (W - padL - padR) / labels.length;
  labels.forEach(function (lb, i) {
    var h = (H - padT - padB) * vals[i] / max, bw = Math.min(30, cw - 16);
    ctx.fillStyle = "#0e7a5f";
    ctx.fillRect(padL + i * cw + (cw - bw) / 2, H - padB - h, bw, h);
    ctx.fillStyle = "#22302b"; ctx.textAlign = "center";
    ctx.fillText(lb, padL + i * cw + cw / 2, H - 8);
  });
}
var mode = "both";
function renderYear() {
  var months = effectiveMonths(); /* 11 月含用户账，其余为示例数 */
